const input = $input.first().json;
const event = input.event || input;
const context = input.context || {};
const message = context.message || context.rawPayload?.message || context.rawPayload?.body || context.rawPayload?.text || '';
const customer = context.customer || {};
const products = context.rawPayload?.availableProducts || context.products || [];

if (!message) {
  return [{
    json: {
      agent: 'customer_intent',
      decision: 'HUMAN_REVIEW',
      reason: 'No customer message provided',
      confidence: 0,
      action: 'HUMAN_HANDOFF',
      channel: 'none',
      message: '',
      escalate: true,
      priority: 'medium',
      customerId: event.customerId || '',
      orderId: event.orderId || '',
      status: 'error_missing_data',
      intent: 'unknown',
      productCriteria: {},
      recommendedProducts: []
    }
  }];
}

return [{
  json: {
    event,
    context,
    message,
    customer,
    availableProducts: products,
    customerId: event.customerId || customer.id || ''
  }
}];

const item = $input.first().json;
let text = item.text || item.output || JSON.stringify(item);
text = String(text).replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    intent: 'unknown',
    confidence: 0.1,
    productCriteria: {},
    recommendedProducts: [],
    recommendedAction: 'HUMAN_HANDOFF',
    replyMessage: '',
    escalate: true,
    priority: 'medium'
  };
}

const upstream = $('Prepare Message Context').first().json;
const allowedActions = ['PRODUCT_RECOMMENDATION','CHECKOUT_ASSISTANCE','ANSWER_QUESTION','HUMAN_HANDOFF','FOLLOW_UP'];
if (!allowedActions.includes(parsed.recommendedAction)) {
  parsed.recommendedAction = 'HUMAN_HANDOFF';
  parsed.escalate = true;
}

// Filter recommended products to only those that exist in available list (safety)
const availableIds = new Set((upstream.availableProducts || []).map(p => String(p.id || p.productId)));
const safeProducts = (parsed.recommendedProducts || []).filter(p => availableIds.size === 0 || availableIds.has(String(p.id)));

return [{
  json: {
    agent: 'customer_intent',
    decision: parsed.recommendedAction,
    reason: `Intent: ${parsed.intent} | confidence ${parsed.confidence}`,
    confidence: Number(parsed.confidence) || 0,
    action: parsed.recommendedAction,
    channel: 'email',
    message: parsed.replyMessage || '',
    escalate: !!parsed.escalate,
    priority: parsed.priority || 'medium',
    customerId: upstream.customerId,
    orderId: upstream.event?.orderId || '',
    status: 'decided',
    intent: parsed.intent,
    productCriteria: parsed.productCriteria || {},
    recommendedProducts: safeProducts
  }
}];

const d = $input.first().json;
return [{
  json: {
    ...d,
    status: d.escalate ? 'escalated' : 'completed'
  }
}];
